{
  "interpretation": {
    "name": "CalibrateNutrunnerThenTightenLine2",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Make the shared nutrunner NR7 available at station st2 so that line 2 can tighten the F30 fasteners. The calibration the operator asked for has no service in the context.",
    "constraints": [
      "NR7 must be reserved exclusively for line 2 for the whole use, then released.",
      "NR7 must be at station st2 before configure-tool or tighten-fasteners is invoked.",
      "The tightening program for F30 must come only from get-program, with no numeric values in the Recipe.",
      "transport-tool must be executed by agvexecutor.",
      "Every tightening must be evaluated and recorded for traceability.",
      "Calibration of NR7 must happen before line 2 uses the tool, but no calibration service is available."
    ],
    "preference": "Return NR7 to the crib after use and release the reservation so that other lines can use it.",
    "priority": "normal",
    "horizon": "Once, before line 2 uses NR7 for the F30 fasteners.",
    "requested_capabilities": ["calibrate-tool"],
    "omit_services": []
  },
  "recipe": {
    "name": "nr7-line2-f30-tightening",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "move-to-station",
        "steps": [
          {
            "name": "reserve-nr7",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "get-f30-program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "move-to-station",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-nr7-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "evaluate-and-record",
        "steps": [
          {
            "name": "configure-nr7",
            "service": "configure-tool",
            "next": ["tighten-nr7"],
            "dep": ["get-f30-program", "reserve-nr7"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-nr7",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure-nr7", "reserve-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "evaluate-and-record",
        "next": "return-and-release",
        "steps": [
          {
            "name": "evaluate-f30-tightening",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-nr7", "get-f30-program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record-f30-tightening",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return-and-release",
        "next": null,
        "steps": [
          {
            "name": "transport-nr7-to-crib",
            "service": "transport-tool",
            "next": ["release-nr7"],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release-nr7",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
